import hashlib
import hmac
import json
from urllib.parse import parse_qsl, quote, urlencode, urlsplit, urlunsplit

_SECRET_PARAMS = {"api_key", "key", "token", "access_token", "refresh_token", "client_secret", "signature", "password"}


class AuthError(Exception):
    def __init__(self, status, message="token request failed"):
        super().__init__(f"{message} ({status})")
        self.status = status


def _canonical(method, path, query, timestamp, body):
    q = "&".join(quote(n, safe="-_.~") + "=" + quote(v, safe="-_.~") for n, v in sorted(query))
    return "\n".join([method.upper(), path, q, str(timestamp), hashlib.sha256(body or b"").hexdigest()])


def _redact(url):
    parts = urlsplit(url)
    pairs = parse_qsl(parts.query, keep_blank_values=True)
    if not any(n.lower() in _SECRET_PARAMS for n, _ in pairs):
        return url
    query = urlencode([(n, "REDACTED" if n.lower() in _SECRET_PARAMS else v) for n, v in pairs])
    return urlunsplit(parts._replace(query=query))


class AuthSession:
    def __init__(self, transport, token_url, client_id, client_secret, signing_secret, clock, margin=30):
        self.transport = transport
        self.token_url = token_url
        self.client_id = client_id
        self.client_secret = client_secret
        self.signing_secret = signing_secret
        self.clock = clock
        self.margin = margin
        self.log = []
        self._token = None
        self._expiry = 0

    def _call(self, method, url, headers, body):
        status, resp_headers, resp_body = self.transport.send(method, url, headers, body, 10)
        self.log.append(f"{method} {_redact(url)} -> {status}")
        return status, resp_headers, resp_body

    def _get_token(self):
        if self._token is not None and self.clock() < self._expiry - self.margin:
            return self._token
        form = urlencode([("grant_type", "client_credentials"), ("client_id", self.client_id), ("client_secret", self.client_secret)])
        headers = {"Content-Type": "application/x-www-form-urlencoded", "Accept": "application/json"}
        status, _h, raw = self._call("POST", self.token_url, headers, form.encode("utf-8"))
        if status != 200:
            raise AuthError(status)
        try:
            data = json.loads(raw)
        except (ValueError, TypeError):
            raise AuthError(status, "token response is not JSON")
        if not isinstance(data, dict):
            raise AuthError(status, "token response is not an object")
        token, kind, lifetime = data.get("access_token"), data.get("token_type"), data.get("expires_in")
        if not isinstance(token, str) or not token:
            raise AuthError(status, "no access token")
        if not isinstance(kind, str) or kind.lower() != "bearer":
            raise AuthError(status, "unsupported token type")
        if not isinstance(lifetime, int) or isinstance(lifetime, bool) or lifetime <= 0:
            raise AuthError(status, "no valid expiry")
        self._token = token
        self._expiry = self.clock() + lifetime
        return token

    def _signed_send(self, method, url, body):
        token = self._get_token()
        parts = urlsplit(url)
        path = parts.path or "/"
        query = parse_qsl(parts.query, keep_blank_values=True)
        timestamp = int(self.clock())
        signature = hmac.new(self.signing_secret, _canonical(method, path, query, timestamp, body).encode("utf-8"), hashlib.sha256).hexdigest()
        headers = {"Authorization": f"Bearer {token}", "X-Timestamp": str(timestamp), "X-Signature": signature}
        if body is not None:
            headers["Content-Type"] = "application/json"
        return self._call(method, url, headers, body)

    def send(self, method, url, body=None):
        response = self._signed_send(method, url, body)
        if response[0] == 401:
            self._token = None
            response = self._signed_send(method, url, body)
        return response

