import hashlib, hmac, json
from urllib.parse import parse_qs, parse_qsl, quote, urlsplit

TOKEN_URL = "https://auth.example.com/oauth/token"
SIGNING = b"sign-me-please"

class Clock:
    def __init__(self, t=10_000):
        self.t = t
    def __call__(self):
        return self.t

def server_canonical(method, path, query, timestamp, body):
    q = "&".join(quote(n, safe="-_.~") + "=" + quote(v, safe="-_.~") for n, v in sorted(query))
    return "\n".join([method.upper(), path, q, str(timestamp), hashlib.sha256(body or b"").hexdigest()])

class FakeServices:
    def __init__(self, clock, token_responses=None, lifetime=3600):
        self.clock = clock
        self.lifetime = lifetime
        self.issued = []
        self.valid = set()
        self.calls = []
        self.token_responses = token_responses
        self.reject_next = 0
    def send(self, method, url, headers, body, timeout):
        self.calls.append((method, url, dict(headers), body, timeout))
        if url == TOKEN_URL:
            if self.token_responses:
                return self.token_responses.pop(0)
            form = parse_qs(body.decode())
            assert headers["Content-Type"] == "application/x-www-form-urlencoded"
            assert form == {"grant_type": ["client_credentials"], "client_id": ["app"], "client_secret": ["cs-XYZ-secret"]}
            token = f"at-{len(self.issued) + 1}"
            self.issued.append(token)
            self.valid.add(token)
            return 200, {"Content-Type": "application/json"}, json.dumps({"access_token": token, "token_type": "bearer", "expires_in": self.lifetime}).encode()
        auth = headers.get("Authorization", "")
        if not auth.startswith("Bearer ") or auth[7:] not in self.valid or self.reject_next:
            self.reject_next = max(0, self.reject_next - 1)
            return 401, {}, b""
        parts = urlsplit(url)
        expected = hmac.new(SIGNING, server_canonical(method, parts.path or "/", parse_qsl(parts.query, keep_blank_values=True), int(headers["X-Timestamp"]), body).encode(), hashlib.sha256).hexdigest()
        if not hmac.compare_digest(expected, headers["X-Signature"]) or int(headers["X-Timestamp"]) != self.clock():
            return 403, {}, b"bad signature"
        if body is not None and headers.get("Content-Type") != "application/json":
            return 415, {}, b""
        return 200, {"Content-Type": "application/json"}, b'{"ok": true}'

def make(lifetime=3600, token_responses=None):
    clock = Clock()
    services = FakeServices(clock, token_responses, lifetime)
    session = AuthSession(services, TOKEN_URL, "app", "cs-XYZ-secret", SIGNING, clock)
    return clock, services, session

@test("a signed request with a fresh token")
def _():
    clock, services, s = make()
    check_eq(s.send("GET", "https://api.example.com/v1/books?limit=5&tag=sf"), (200, {"Content-Type": "application/json"}, b'{"ok": true}'))
    check_eq(services.issued, ["at-1"])
    check_eq([c[0] for c in services.calls], ["POST", "GET"])
    check_eq(services.calls[1][4], 10)

@test("bodies are signed too")
def _():
    clock, services, s = make()
    check_eq(s.send("POST", "https://api.example.com/v1/books", b'{"title":"Dune"}')[0], 200)
    check_eq(s.send("DELETE", "https://api.example.com")[0], 200)

@test("tokens are cached and renewed")
def _():
    clock, services, s = make(lifetime=100)
    s.send("GET", "https://api.example.com/a")
    clock.t += 69
    s.send("GET", "https://api.example.com/b")
    check_eq(services.issued, ["at-1"])
    clock.t += 1
    s.send("GET", "https://api.example.com/c")
    check_eq(services.issued, ["at-1", "at-2"])

@test("one retry after a 401")
def _():
    clock, services, s = make()
    s.send("GET", "https://api.example.com/a")
    services.valid.clear()
    clock.t += 5
    check_eq(s.send("GET", "https://api.example.com/b")[0], 200)
    check_eq(services.issued, ["at-1", "at-2"])
    services.reject_next = 5
    check_eq(s.send("GET", "https://api.example.com/c")[0], 401)
    check_eq(services.issued, ["at-1", "at-2", "at-3"])

@test("broken token responses")
def _():
    for response in [(500, {}, b""), (200, {}, b"not json"), (200, {}, b'{"access_token": "t", "token_type": "mac", "expires_in": 60}'),
                     (200, {}, b'{"token_type": "Bearer", "expires_in": 60}'), (200, {}, b'{"access_token": "t", "token_type": "Bearer", "expires_in": "60"}')]:
        clock, services, s = make(token_responses=[response])
        try:
            s.send("GET", "https://api.example.com/a")
            check(False, f"expected AuthError for {response}")
        except AuthError as e:
            check_eq(e.status, response[0])

@test("the log has every call and no secret")
def _():
    clock, services, s = make()
    s.send("GET", "https://api.example.com/v1/books?limit=5&access_token=leaky")
    services.valid.clear()
    s.send("POST", "https://api.example.com/v1/books", b"{}")
    check_eq(s.log, [
        "POST https://auth.example.com/oauth/token -> 200",
        "GET https://api.example.com/v1/books?limit=5&access_token=REDACTED -> 200",
        "POST https://api.example.com/v1/books -> 401",
        "POST https://auth.example.com/oauth/token -> 200",
        "POST https://api.example.com/v1/books -> 200",
    ])
    text = "\n".join(s.log)
    for secret in ("cs-XYZ-secret", "sign-me-please", "at-1", "at-2", "leaky"):
        check(secret not in text, f"{secret} is in the log")

